    lauf_id: `pruefstand-${f.id}`,
    umschlag: {
      lauf: { lauf_nr: `pruefstand-${f.id}`, pruefstand: true, liefermodus: 'test', gestartet_am: start },
      konzept: { kp_id: 'PRUEFSTAND', prozess: f.prozess },
      plan: {},
      potenziale: [],
      protokoll: [],
      aggregat: {
        prozess: `${f.titel}: ${f.prozess}`,
        schmerzpunkte: [],
        risiken: [],
        datenarten: { als_text: NICHT_AUSGEWERTET },
        tragweite: { als_text: NICHT_AUSGEWERTET },
        epics: [{
          epic_id: `ep-${f.id.toLowerCase()}`,
          titel: f.titel,
          ziel: f.prozess,
          stories: f.stories.map(([titel, beschreibung], i) => ({ story_id: `${f.id.toLowerCase()}-${i + 1}`, titel, beschreibung })),
        }],
      },
    },
  },
}));

// Precision, Recall und F1 der Risikoklasse (P4). Ein Fall ohne lesbare Klasse zählt als falsch.
const faelle = $('Fälle laden').all().map(i => i.json);
const antworten = $input.all().map(i => i.json);
const KLASSEN = ['unacceptable', 'high', 'limited', 'minimal'];
const flach = t => String(t || '').toLowerCase().replace(/\s+/g, ' ');

// Fundstelle der Antwort mit der Soll-Fundstelle vergleichen (nur Nummer und Buchstabe)
function fundstelleTrifft(soll, c) {
  if (!soll) return null;
  const s = flach(soll);
  const text = flach(JSON.stringify([c.anhang_iii_kategorie, c.pflichten, c.begruendung_ampel]));
  let m = s.match(/art\. 5 abs\. 1 buchst\. ([a-h])/);
  if (m) return new RegExp(String.raw`(art\.?|artikel) ?5 (abs\.?|absatz) ?1 (buchst\.?|buchstabe|lit\.?) ?${m[1]}\b`).test(text);
  m = s.match(/art\. 50 abs\. (\d)/);
  if (m) return new RegExp(String.raw`(art\.?|artikel) ?50 (abs\.?|absatz) ?${m[1]}\b`).test(text);
  m = s.match(/anhang iii nr\. (\d)(?: buchst\. ([a-e]))?/);
  if (m) {
    const ist = flach(c.anhang_iii_kategorie).match(/nr\.? ?(\d+)(?:[^a-z0-9]{0,20}(?:buchst\w*\.?|lit\.?)? ?([a-e])\b)?/);
    return !!ist && ist[1] === m[1] && (!m[2] || ist[2] === m[2]);
  }
  return null;
}

const ergebnisse = faelle.map(f => {
  const a = antworten.find(x => x.lauf_id === f.lauf_id) || {};
  const c = a.umschlag?.compliance || {};
  const bc30 = (a.umschlag?.protokoll || []).filter(p => p.stufe === 'BC3-30 Compliance prüfen').slice(-1)[0] || {};
  return {
    id: f.fall.id,
    titel: f.fall.titel,
    soll: f.fall.soll_klasse,
    ist: c.ai_act_klasse || null,
    ampel: c.ampel || null,
    soll_fundstelle: f.fall.soll_fundstelle,
    ist_fundstelle: c.anhang_iii_kategorie || null,
    fundstelle_trifft: c.ai_act_klasse ? fundstelleTrifft(f.fall.soll_fundstelle, c) : false,
    richtig: c.ai_act_klasse === f.fall.soll_klasse,
    befunde: [...(c.einstufung_strittig || []), ...(a.error ? [String(a.error.message || a.error)] : [])],
    modell: (bc30.modelle || [])[0]?.modell || null,
  };
});

const runde = x => Math.round(x * 1000) / 1000;
function masse(tp, fp, fn) {
  const p = tp + fp ? tp / (tp + fp) : 0;
  const r = tp + fn ? tp / (tp + fn) : 0;
  return { tp, fp, fn, precision: runde(p), recall: runde(r), f1: runde(p + r ? 2 * p * r / (p + r) : 0) };
}
const je_klasse = Object.fromEntries(KLASSEN.map(k => [k, masse(
  ergebnisse.filter(e => e.ist === k && e.soll === k).length,
  ergebnisse.filter(e => e.ist === k && e.soll !== k).length,
  ergebnisse.filter(e => e.soll === k && e.ist !== k).length)]));
const hr = x => x === 'high' || x === 'unacceptable';
const hochrisiko = masse(
  ergebnisse.filter(e => hr(e.ist) && hr(e.soll)).length,
  ergebnisse.filter(e => hr(e.ist) && !hr(e.soll)).length,
  ergebnisse.filter(e => hr(e.soll) && !hr(e.ist)).length);
const mitFundstelle = ergebnisse.filter(e => e.soll_fundstelle);

return [{
