    modell: ergebnisse.find(e => e.modell)?.modell || null,
    anzahl_faelle: ergebnisse.length,
    anzahl_gelesen: ergebnisse.filter(e => e.ist).length,
    anzahl_richtig: ergebnisse.filter(e => e.richtig).length,
    macro_f1: runde(KLASSEN.reduce((s, k) => s + je_klasse[k].f1, 0) / KLASSEN.length),
    hochrisiko_precision: hochrisiko.precision,
    hochrisiko_recall: hochrisiko.recall,
    hochrisiko_f1: hochrisiko.f1,
    fundstelle_treffer: mitFundstelle.filter(e => e.fundstelle_trifft).length,
    fundstelle_von: mitFundstelle.length,
    je_klasse: JSON.stringify(je_klasse),
    faelle: JSON.stringify(ergebnisse),
    bemerkung: 'BC3-30 ohne Regel R2, eigene Testfälle (16), Soll-Werte von Svetlana bestätigt',
